//! Static route and browser-contract coverage for the published Constitution page.

const MAIN_RS: &str = include_str!("../src/main.rs");
const HANDLER_RS: &str = include_str!("../src/handlers/repository/constitution.rs");
const CONSTITUTION_PAGE: &str = include_str!("../static/constitution.html");

#[test]
fn constitution_page_is_served_by_the_existing_tenant_scoped_handler_module() {
    assert!(
        MAIN_RS.contains(".route(\"/constitution\", get(constitution_page))"),
        "Bridge must serve the Constitution page at /constitution"
    );
    assert!(
        HANDLER_RS.contains("get_publication(&state.tenant_id, &repository_id"),
        "the Constitution response must resolve publication provenance inside the tenant and repository scope"
    );
}

#[test]
fn constitution_page_reads_only_the_existing_constitution_endpoint() {
    for required in [
        "fetch(endpoint())",
        "/api/v1/repositories/${encodeURIComponent(elements.repository.value.trim())}/constitution",
        "source_reference",
        "source_digest_hex",
        "startVisibleRefresh(load, intervalMs)",
        "document.visibilityState === \"visible\"",
    ] {
        assert!(
            CONSTITUTION_PAGE.contains(required),
            "constitution.html is missing {required}"
        );
    }
    assert_eq!(
        CONSTITUTION_PAGE.matches("fetch(").count(),
        1,
        "the Constitution page must use exactly one read endpoint"
    );
    for mutating_verb in ["\"POST\"", "\"PUT\"", "\"PATCH\"", "\"DELETE\""] {
        assert!(
            !CONSTITUTION_PAGE.contains(mutating_verb),
            "the Constitution page must not introduce a mutating request ({mutating_verb})"
        );
    }
}

#[test]
fn constitution_page_marks_its_navigation_entry_current() {
    // The nav itself is now rendered by the shared chrome.js from a single
    // NAV_ITEMS source (see nav_consistency.rs); this page only needs to
    // carry the mount point and declare itself as the current capability.
    assert!(
        CONSTITUTION_PAGE.contains("data-bridge-nav"),
        "the Constitution page must carry the shared Bridge nav mount point"
    );
    assert!(
        CONSTITUTION_PAGE.contains("data-current=\"constitution\""),
        "the Constitution page must mark its own shared navigation entry current"
    );
}
